import { publicFields, totalAge, parseAmount } from './module.mjs';
const NAMES = ['kim','lee','park','choi','jung'];
const ri = (a,b)=>a+Math.floor(Math.random()*(b-a+1));
const pick = (a,n)=>a[ri(0,a.length-1)];
// lodash reference semantics (lodash pick: keys with hasIn; sumBy: sum of property; toNumber: trim, bad signed hex -> NaN, else +value)
const refPick = (row)=>({id:row.id,name:row.name});
const refSum = (rows)=>{let s=0; for(const r of rows) s+=r.age; return s;};
const refToNumber = (v)=>{ const t=v.replace(/^\s+|\s+$/g,''); if(/^0b[01]+$/i.test(t)||/^0o[0-7]+$/i.test(t)) return parseInt(t.slice(2), /^0b/i.test(t)?2:8); if(/^[-+]0x[0-9a-f]+$/i.test(t)) return NaN; return +t; };
const same=(a,b)=>Object.is(a,b)||JSON.stringify(a)===JSON.stringify(b);
let fail=0;
// examples
const ex = [
 ['pick', publicFields({id:1,name:'jung',age:24}), {id:1,name:'jung'}],
 ['pick', publicFields({id:8,name:'choi',age:47}), {id:8,name:'choi'}],
 ['sum', totalAge([{id:9,name:'kim',age:45},{id:6,name:'park',age:30},{id:9,name:'lee',age:49}]), 124],
 ['sum', totalAge([{id:3,name:'park',age:56},{id:8,name:'park',age:55},{id:1,name:'choi',age:32},{id:0,name:'jung',age:26},{id:5,name:'park',age:21},{id:8,name:'choi',age:26},{id:0,name:'park',age:31},{id:6,name:'lee',age:41}]), 288],
 ['num', parseAmount('92858+99'), NaN],
 ['num', parseAmount('.72e'), NaN],
];
for (const [k,got,exp] of ex){ const ok=same(got,exp); if(!ok) fail++; console.log(ok?'ok  ':'FAIL', k, JSON.stringify(got), 'expected', JSON.stringify(exp)); }
// random
const CH='0123456789.+- ex';
for (let i=0;i<200000;i++){
  const n=ri(0,8); let s=''; for(let j=0;j<n;j++) s+=CH[ri(0,CH.length-1)];
  if(!same(parseAmount(s), refToNumber(s))){ if(fail<10) console.log('FAIL num', JSON.stringify(s), parseAmount(s), refToNumber(s)); fail++; }
}
for (let i=0;i<20000;i++){
  const row={id:ri(0,9),name:pick(NAMES),age:ri(18,60)};
  if(!same(publicFields(row), refPick(row))){ fail++; if(fail<10) console.log('FAIL pick', row); }
  const rows=Array.from({length:ri(0,12)},()=>({id:ri(0,9),name:pick(NAMES),age:ri(18,60)}));
  if(totalAge(rows)!==refSum(rows)){ fail++; if(fail<10) console.log('FAIL sum', rows); }
}
console.log(fail===0 ? 'ALL CHECKS PASSED' : `FAILURES: ${fail}`);
EOF
cd "$S" && node check.mjs

